const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
const date = value => value ? new Date(value).toLocaleString('fr-FR', { dateStyle:'short', timeStyle:'short' }) : '—';
const labels = { pending:'À traiter', resolved:'Traité', dismissed:'Classé sans suite', public:'Salon public', private:'Message privé', group:'Groupe', profile:'Profil',
  harassment:'Harcèlement', spam:'Spam ou publicité', inappropriate:'Contenu inapproprié', fake:'Faux profil', other:'Autre',
  active:'Actif', trialing:'Essai', canceled:'Résilié', past_due:'Paiement en retard', unpaid:'Impayé', incomplete:'Incomplet', incomplete_expired:'Expiré', free:'Gratuit',
  report_updated:'Signalement mis à jour', report_resolved:'Signalement traité', report_dismissed:'Signalement classé', report_reopened:'Signalement rouvert',
  message_deleted:'Message supprimé', message_pinned:'Message épinglé', message_unpinned:'Épingle retirée', user_suspended:'Compte suspendu', user_unsuspended:'Compte réactivé',
  profile_verified:'Profil vérifié', profile_unverified:'Badge retiré', note:'Note interne', warn:'Avertissement', clear_bio:'Biographie retirée', clear_photo:'Photo retirée',
  revoke_sessions:'Sessions révoquées', room_updated:'Salon modifié', group_paused:'Groupe mis en pause', group_resumed:'Groupe réouvert' };
const badge = (value, tone='') => `<span class="adm-badge ${tone}">${escape(labels[value] || value)}</span>`;
const options = (items, selected='') => items.map(([v,l]) => `<option value="${escape(v)}" ${v===String(selected)?'selected':''}>${escape(l)}</option>`).join('');
const button = (action, text, extra='', danger=false) => `<button type="button" data-do="${action}" ${extra} class="${danger?'adm-danger':''}">${text}</button>`;
const userButton = (id,name) => button('member',escape(name || 'Compte supprimé'),`data-id="${escape(id)}"`);
const empty = text => `<div class="adm-empty"><span>✓</span><h3>${escape(text)}</h3><p>Vous pouvez changer les filtres ou actualiser la liste.</p></div>`;
const nav = [ ['overview','Vue d’ensemble','01'], ['reports','Signalements','02'], ['members','Membres','03'], ['rooms','Salons','04'], ['groups','Groupes','05'], ['subscriptions','Abonnements','06'], ['journal','Journal','07'], ['system','État du service','08'] ];
export function installAdminUI({ api, getUser }) {
  const root = document.createElement('dialog'); root.id='adminModal'; root.className='admin-console'; root.setAttribute('aria-labelledby','admTitle');
  root.innerHTML=`<div class="adm-shell"><aside class="adm-sidebar"><div class="adm-brand"><span>L</span><div>Letchat<small>ADMINISTRATION</small></div></div><nav aria-label="Rubriques de l’administration">${nav.map(([id,title,n])=>`<button type="button" data-tab="${id}"><span>${n}</span>${title}</button>`).join('')}</nav><p class="adm-sidebar-note">Un espace pour prendre soin de votre communauté.</p></aside><div class="adm-main"><header class="adm-header"><div><p class="adm-eyebrow">ESPACE ADMINISTRATEUR</p><h1 id="admTitle">Vue d’ensemble</h1><p id="admSubtitle"></p></div><div class="adm-header-actions"><button type="button" data-do="refresh" aria-label="Actualiser cette rubrique">Actualiser</button><button type="button" data-do="close" class="adm-exit">Retour au tchat ×</button></div></header><p class="adm-feedback" role="status" aria-live="polite"></p><p class="adm-error" role="alert" hidden></p><div class="adm-filters"></div><main class="adm-content" tabindex="-1"></main><footer class="adm-footer"></footer></div></div>`;
  document.body.append(root);
  const $ = selector => root.querySelector(selector), content=$('.adm-content'), filters=$('.adm-filters');
  const sub=document.createElement('dialog');sub.className='adm-subdialog';sub.setAttribute('aria-labelledby','admSubTitle');document.body.append(sub);
  const json=async(path,method='GET',body)=>(await api(path,{method,...(body===undefined?{}:{headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})})).json();
  const mediaUrls = new Set();
  function clearMedia(){ for(const url of mediaUrls)URL.revokeObjectURL(url);mediaUrls.clear(); }
  sub.addEventListener('close',clearMedia);
  let tab='overview', page=1, query={}, revision=0, owner='', data, memberId='', subRevision=0;
  const error=e=>{ const el=$('.adm-error');el.hidden=false;el.textContent=e.message||String(e); };
  const success=text=>{$('.adm-feedback').textContent=text;$('.adm-error').hidden=true;};
  function reset(){ revision++;subRevision++;owner='';content.innerHTML='';sub.innerHTML='';if(sub.open)sub.close();if(root.open)root.close(); }
  function valid(ticket){ return ticket===revision && root.open && getUser()?.id===owner && getUser()?.admin; }
  const subtitles={overview:'L’activité de votre communauté, en un regard.',reports:'Examinez les signalements et gardez une trace de vos décisions.',members:'Recherchez un membre et consultez son dossier de modération.',rooms:'Supervisez les salons et leurs messages publics.',groups:'Gérez les groupes et interrompez les échanges si nécessaire.',subscriptions:'Suivez les droits Premium et les statuts synchronisés avec Stripe.',journal:'Retrouvez qui a fait quoi, quand et pour quel motif.',system:'Vérifiez les principaux services de Letchat.'};
  function searchFields(){
    const select=(name,title,items)=>`<label>${title}<select name="${name}">${options(items,query[name]||'')}</select></label>`;
    let fields='';
    if(['reports','members','groups','subscriptions','journal'].includes(tab)) fields=`<label class="adm-search">Recherche<input type="search" name="q" maxlength="100" value="${escape(query.q||'')}" placeholder="${tab==='members'?'Nom, identifiant, e-mail ou ville…':'Nom, mot-clé ou numéro…'}"></label>`;
    if(tab==='members')fields+=select('filter','Afficher',[['','Tous les membres'],['online','En ligne'],['suspended','Suspendus'],['premium','Premium'],['verified','Vérifiés'],['guest','Invités']]);
    if(tab==='reports')fields+=select('status','Statut',[['pending','À traiter'],['resolved','Traités'],['dismissed','Classés'],['all','Tous']])+select('kind','Origine',[['','Toutes'],['public','Salons'],['private','Messages privés'],['group','Groupes'],['profile','Profils']])+select('priority','Priorité',[['','Toutes'],['urgent','Urgente'],['normal','Normale']])+`<label class="adm-checkbox"><input name="mine" type="checkbox" ${query.mine==='true'?'checked':''}> Mes dossiers</label>`;
    if(tab==='groups')fields+=select('filter','Afficher',[['','Tous les groupes'],['paused','En pause']]);
    if(tab==='subscriptions')fields+=select('status','Statut',[['','Tous les statuts'],...['active','trialing','past_due','unpaid','canceled','incomplete','incomplete_expired'].map(k=>[k,labels[k]])]);
    if(tab==='journal')fields+=select('action','Intervention',[['','Toutes'],...['report_updated','user_suspended','user_unsuspended','warn','note','clear_bio','clear_photo','revoke_sessions','message_deleted','message_pinned','profile_verified','room_updated','group_paused','group_resumed'].map(k=>[k,labels[k]])]);
    filters.innerHTML=fields?`<form class="adm-filter-form">${fields}<button type="submit" class="adm-primary">Rechercher</button></form>`:'';
    const form=filters.querySelector('form');if(form)form.onsubmit=e=>{e.preventDefault();query=Object.fromEntries(new FormData(form));if(query.mine)query.mine='true';page=1;load();};
  }
  function pagination(result){
    const pages=Math.max(1,Math.ceil(result.total/result.pageSize));
    $('.adm-footer').innerHTML=`<span>${result.total} résultat${result.total!==1?'s':''} · Page ${page} sur ${pages}</span><div>${button('prev','Précédent',page<=1?'disabled':'')}${button('next','Suivant',page>=pages?'disabled':'')}</div>`;
  }
  function table(head,rows){return `<div class="adm-table-wrap"><table><thead><tr>${head.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>{let i=0;return row.replace(/<td>/g,()=>`<td data-label="${escape(head[i++]||'Actions')}">`);}).join('')}</tbody></table></div>`;}
  function history(rows){return rows.length?`<ol class="adm-timeline">${rows.map(r=>`<li><div><strong>${escape(labels[r.action]||r.action)}</strong><time>${date(r.created_at)}</time></div><p>${escape(r.details)}</p><small>Par ${escape(r.admin_name)}${r.target_name?' · '+escape(r.target_name):''}${r.report_id?' · signalement #'+escape(r.report_id):''}</small></li>`).join('')}</ol>`:empty('Aucune intervention enregistrée');}
  async function load(){
    const ticket=++revision;searchFields();$('.adm-error').hidden=true;$('.adm-footer').innerHTML='';content.setAttribute('aria-busy','true');content.innerHTML='<p class="adm-loading">Chargement des données…</p>';
    $('#admTitle').textContent=nav.find(n=>n[0]===tab)[1];$('#admSubtitle').textContent=subtitles[tab];
    root.querySelectorAll('[data-tab]').forEach(el=>{el.classList.toggle('selected',el.dataset.tab===tab);if(el.dataset.tab===tab)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
    try {
      const paths={overview:'stats',members:'profiles',reports:'reports',rooms:'rooms',groups:'groups',subscriptions:'subscriptions',journal:'moderation-log',system:'system'};
      const result=await json(`/api/admin/${paths[tab]}?${new URLSearchParams({...query,page})}`);if(!valid(ticket))return;data=result;
      if(tab==='overview'){
        const cards=[['En ligne maintenant',result.online,'Membres connectés'],['Signalements à traiter',result.pendingReports,`${result.urgent} urgent(s) · ${result.overdue} depuis plus de 24 h`],['Membres',result.users,`${result.guests} invité(s) temporaire(s)`],['Messages sur 24 h',result.messages24h,`${result.public24h} publics · ${result.private24h} privés · ${result.group24h} en groupe`],['Premium actifs',result.premium,'Droits actuellement valides'],['Suspensions actives',result.activeSuspensions,`${result.groups} groupe(s) sur le site`]];
        content.innerHTML=`<section class="adm-welcome"><div><span class="adm-eyebrow">VOTRE COMMUNAUTÉ</span><h2>Une vue claire pour agir.</h2><p>${result.pendingReports?'Des signalements attendent votre examen.':'Aucun signalement en attente. Profitez-en pour faire le point sur la communauté.'}</p></div>${button('go-reports','Examiner les signalements →','')}</section><div class="adm-stats">${cards.map(([label,n,detail])=>`<article><h3>${label}</h3><strong>${n}</strong><p>${detail}</p></article>`).join('')}</div><section class="adm-card"><h2>Accès rapides</h2><div class="adm-actions">${button('go-members','Rechercher un membre')}${button('go-rooms','Gérer les salons')}${button('go-journal','Voir les dernières interventions')}</div><p class="adm-muted">Les compteurs de messages portent sur les données encore conservées. Les messages expirent après 48 heures.</p></section>`;
        $('.adm-footer').textContent=`Actualisé le ${date(result.updatedAt)}`;
      }
      if(tab==='members')content.innerHTML=result.items.length?table(['Membre','Localisation','État','Dernière activité',''],result.items.map(p=>`<tr><td><strong>${escape(p.display_name)}</strong><small>${escape(p.username||p.email||p.user_id)}</small></td><td>${escape(p.city||'—')}</td><td>${p.online?badge('En ligne','green'):''}${p.suspended?badge('Suspendu','red'):''}${p.premium?badge('Premium','gold'):''}${p.verified?badge('Vérifié','blue'):''}${p.is_guest?badge('Invité'):''}</td><td>${date(p.last_seen)}</td><td>${userButton(p.user_id,'Ouvrir le dossier')}</td></tr>`)):empty('Aucun membre trouvé');
      if(tab==='reports')content.innerHTML=result.items.length?result.items.map(r=>`<article class="adm-card adm-report" data-report="${r.id}"><div class="adm-card-head"><div><small>SIGNALEMENT #${r.id} · ${date(r.created_at)}</small><h2>${escape(labels[r.reason]||r.reason)}</h2></div><div>${badge(r.status)}${r.priority==='urgent'?badge('Urgent','red'):''}${badge(r.message_kind||'profile','blue')}</div></div><div class="adm-report-people"><span>Membre concerné ${userButton(r.reported_id,r.reported_name)}</span><span>Signalé par ${escape(r.reporter_name)}</span></div>${r.context_label?`<p class="adm-muted">${escape(r.context_label)}</p>`:''}${r.evidence_body?`<blockquote>${escape(r.evidence_body)}</blockquote>`:''}${r.details?`<p>${escape(r.details)}</p>`:''}${r.content_removed_at?`<p class="adm-muted">Contenu retiré le ${date(r.content_removed_at)}</p>`:''}<p class="adm-muted">${r.assignee_name?'Pris en charge par '+escape(r.assignee_name):'Non attribué'}</p>${r.admin_note?`<p class="adm-internal"><b>Note interne :</b> ${escape(r.admin_note)}</p>`:''}<div class="adm-actions">${r.media_available?button('report-media','Voir la pièce jointe',`data-id="${r.id}"`):''}${button('report-edit','Examiner / décider',`data-id="${r.id}"`)}${button('report-assign',r.assigned_to===owner?'Libérer le dossier':'Prendre en charge',`data-id="${r.id}"`)}${button('report-priority',r.priority==='urgent'?'Priorité normale':'Marquer urgent',`data-id="${r.id}"`)}${r.message_id&&!r.content_removed_at?button('report-delete','Retirer le message',`data-id="${r.id}"`,true):''}</div></article>`).join(''):empty('Aucun signalement dans cette sélection');
      if(tab==='rooms')content.innerHTML=`<div class="adm-room-grid">${result.map(r=>`<article class="adm-card"><div class="adm-card-head"><h2>${escape(r.title)}</h2>${r.read_only?badge('Lecture seule','red'):badge('Ouvert','green')}</div><p>${escape(r.welcome)}</p><div class="adm-room-numbers"><span><b>${r.online}</b> en ligne</span><span><b>${r.messages}</b> messages</span></div>${r.slow_seconds?`<p>Mode lent : ${r.slow_seconds} secondes</p>`:''}${r.notice?`<blockquote>${escape(r.notice)}</blockquote>`:''}${r.premium?badge('Réservé Premium','gold'):''}<div class="adm-actions">${button('room-settings','Paramètres',`data-id="${escape(r.id)}"`)}${button('room-messages','Modérer les messages',`data-id="${escape(r.id)}"`)}</div></article>`).join('')}</div>`;
      if(tab==='groups')content.innerHTML=`<p class="adm-explainer">Les échanges d’un groupe sont accessibles à la modération lorsqu’un membre signale un message. Une pause bloque les nouveaux messages et la visio du groupe.</p>`+(result.items.length?table(['Groupe','Créateur','Activité','État',''],result.items.map(g=>`<tr><td><strong>${escape(g.name)}</strong><small>Créé le ${date(g.created_at)}</small></td><td>${userButton(g.owner_id,g.owner_name)}</td><td>${g.members} membre(s)<small>${g.messages} message(s) conservé(s)</small></td><td>${badge(g.paused?'En pause':'Ouvert',g.paused?'red':'green')}${g.moderation_reason?`<small>${escape(g.moderation_reason)}</small>`:''}</td><td>${button('group-pause',g.paused?'Réouvrir':'Mettre en pause',`data-id="${escape(g.id)}"`,!g.paused)}</td></tr>`)):empty('Aucun groupe trouvé'));
      if(tab==='subscriptions')content.innerHTML=`<p class="adm-explainer">Cette vue affiche les statuts reçus de Stripe. Pour les paiements, remboursements et résiliations, utilisez votre tableau de bord Stripe.</p>`+(result.items.length?table(['Membre','Formule','Statut Stripe','Droits Letchat','Fin de période'],result.items.map(s=>`<tr><td>${userButton(s.user_id,s.display_name)}</td><td>${s.plan==='premium_plus'?'Premium+':'Premium'}</td><td>${badge(s.status)}</td><td>${badge(s.access_active?'Actifs':'Inactifs',s.access_active?'green':'')}</td><td>${date(s.current_period_end)}</td></tr>`)):empty('Aucun abonnement dans cette sélection'));
      if(tab==='journal')content.innerHTML=history(result.items);
      if(tab==='system')content.innerHTML=`<div class="adm-stats adm-system"><article><h3>Base de données</h3><strong class="adm-ok">Disponible</strong><p>Réponse en ${result.databaseMs} ms</p></article><article><h3>Notifications push</h3><strong>${result.pushConfigured?'Configurées':'À configurer'}</strong><p>La réception dépend aussi de l’autorisation du navigateur.</p></article><article><h3>Paiements Stripe</h3><strong>${result.billingConfigured?'Configurés':'À configurer'}</strong><p>Vérification de la présence de la configuration.</p></article></div><section class="adm-card"><h2>Informations du service</h2><dl class="adm-details"><dt>Version</dt><dd>${escape(result.version)}</dd><dt>Processus démarré depuis</dt><dd>${Math.floor(result.uptimeSeconds/3600)} h ${Math.floor(result.uptimeSeconds/60)%60} min</dd><dt>Heure du serveur</dt><dd>${date(result.serverTime)}</dd><dt>Accès administrateurs</dt><dd>${result.adminCount.ids} identifiant(s) · ${result.adminCount.emails} e-mail(s) configuré(s)</dd><dt>Conservation des messages</dt><dd>${result.retentionHours} heures</dd></dl><p class="adm-muted">Les accès administrateurs sont définis dans les variables ADMIN_UID / ADMIN_EMAIL du service Render. Les clés et mots de passe ne sont jamais affichés ici.</p></section>`;
      if(result.items)pagination(result);
    }catch(e){if(valid(ticket)){content.innerHTML=empty('Chargement impossible');error(e);}}
    finally{if(ticket===revision)content.removeAttribute('aria-busy');}
  }
  function go(next){tab=next;page=1;query=next==='reports'?{status:'pending'}:{};$('.adm-feedback').textContent='';load();}
  function openSub(title,html){clearMedia();subRevision++;sub.innerHTML=`<header><h2 id="admSubTitle">${escape(title)}</h2><button type="button" data-sub-close aria-label="Fermer cette fenêtre">×</button></header><p class="adm-sub-error" role="alert" hidden></p><div class="adm-sub-content">${html}</div>`;sub.querySelector('[data-sub-close]').onclick=()=>{subRevision++;sub.close();};if(!sub.open)sub.showModal();}
  function formDialog(title,fields,submit,label='Confirmer'){
    openSub(title,`<form class="adm-edit-form">${fields}<div class="adm-actions"><button type="submit" class="adm-primary">${escape(label)}</button><button type="button" data-cancel>Annuler</button></div></form>`);
    sub.querySelector('[data-cancel]').onclick=()=>sub.close();
    const currentSub=subRevision;const form=sub.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('[type=submit]');b.disabled=true;try{await submit(Object.fromEntries(new FormData(form)));if(getUser()?.id!==owner||!root.open)return;if(currentSub===subRevision)sub.close();success('Modification enregistrée.');await load();}catch(err){if(currentSub===subRevision){const el=sub.querySelector('.adm-sub-error');el.hidden=false;el.textContent=err.message;}}finally{b.disabled=false;}};
  }
  const reasonField=(title='Motif de l’intervention',value='')=>`<label>${title}<textarea name="reason" required minlength="3" maxlength="500" rows="3">${escape(value)}</textarea></label>`;
  async function member(id){
    memberId=id;openSub('Dossier du membre','<p>Chargement…</p>');const ticket=subRevision;
    try{const m=await json(`/api/admin/profiles/${encodeURIComponent(id)}`);if(ticket!==subRevision||!sub.open||getUser()?.id!==owner)return;
      openSub(m.display_name,`<div class="adm-member-status">${m.protected?badge('Administrateur protégé','blue'):''}${m.suspended?badge('Suspendu','red'):badge('Actif','green')}${m.premium?badge('Premium','gold'):''}${m.verified?badge('Vérifié','blue'):''}</div><dl class="adm-details"><dt>Identifiant de connexion</dt><dd>${escape(m.username||m.email||'Compte Google')}</dd><dt>Identifiant interne</dt><dd class="adm-id">${escape(m.user_id)}</dd><dt>Ville</dt><dd>${escape(m.city||'—')}</dd><dt>Type</dt><dd>${m.is_guest?'Invité temporaire':'Compte permanent'}</dd><dt>Dernière activité</dt><dd>${date(m.last_seen)}</dd><dt>Signalements reçus</dt><dd>${m.counts.reports}</dd><dt>Groupes rejoints</dt><dd>${m.counts.groups}</dd></dl>${m.bio?`<blockquote>${escape(m.bio)}</blockquote>`:''}${m.suspended?`<p class="adm-internal">Suspension : ${escape(m.suspension_reason)}<br>Fin : ${m.suspended_until?date(m.suspended_until):'Indéfinie'}</p>`:''}<div class="adm-actions">${button('verify',m.verified?'Retirer le badge':'Vérifier le profil',`data-verified="${!m.verified}"`)}${button('note','Ajouter une note interne')}${!m.protected?button('warn','Avertir')+button(m.suspended?'unsuspend':'suspend',m.suspended?'Lever la suspension':'Suspendre','',!m.suspended)+button('revoke_sessions','Déconnecter les sessions')+(m.bio?button('clear_bio','Retirer la biographie','',true):'')+(m.has_photo?button('clear_photo','Retirer la photo','',true):''):''}</div><h3>Dernières interventions</h3>${history(m.history)}`);
      sub.querySelectorAll('[data-do]').forEach(b=>b.onclick=()=>memberAction(b,m).catch(e=>{const el=sub.querySelector('.adm-sub-error');el.hidden=false;el.textContent=e.message;}));
    }catch(e){if(ticket===subRevision){sub.querySelector('.adm-sub-content').textContent=e.message;}}
  }
  async function memberAction(b,m){
    const action=b.dataset.do,id=encodeURIComponent(m.user_id);
    if(action==='verify'){b.disabled=true;try{await json(`/api/admin/profiles/${id}/verification`,'PATCH',{verified:b.dataset.verified==='true'});await member(m.user_id);await load();}finally{b.disabled=false;}return;}
    if(action==='suspend')return formDialog(`Suspendre ${m.display_name}`,`<p>Le membre sera déconnecté et ne pourra plus utiliser le tchat pendant la suspension.</p><label>Durée<select name="duration">${options([['1h','1 heure'],['24h','24 heures'],['7d','7 jours'],['30d','30 jours'],['permanent','Indéfiniment']],'24h')}</select></label>${reasonField()}`,b=>json(`/api/admin/suspensions/${id}`,'POST',b),'Suspendre ce compte');
    if(action==='unsuspend')return formDialog('Lever la suspension',reasonField(),b=>json(`/api/admin/suspensions/${id}`,'DELETE',b),'Réactiver le compte');
    const descriptions={warn:'Ce texte sera envoyé au membre dans ses notifications.',note:'Cette note reste visible uniquement dans l’administration.',clear_photo:'La photo sera retirée du profil et des messages conservés.',clear_bio:'La biographie du profil sera effacée.',revoke_sessions:'Le membre devra se reconnecter. Son mot de passe reste inchangé.'};
    formDialog(labels[action],`<p>${descriptions[action]}</p>${reasonField(action==='warn'?'Texte de l’avertissement':action==='note'?'Note interne':'Motif')}`,b=>json(`/api/admin/profiles/${id}/actions`,'POST',{...b,action}));
  }
  let roomMessagePage=1,roomMessageId='';
  async function roomMessages(id,number=1){
    roomMessagePage=number;roomMessageId=id;openSub('Messages du salon','<p>Chargement…</p>');const ticket=subRevision;
    try{const r=await json(`/api/admin/rooms/${encodeURIComponent(id)}/messages?page=${number}`);if(ticket!==subRevision||!sub.open)return;
      openSub('Messages du salon',`<p class="adm-muted">${r.total} message(s) conservé(s) · page ${number}</p>${r.items.length?r.items.map(m=>`<article class="adm-card"><div class="adm-card-head"><strong>${escape(m.author)}</strong><time>${date(m.created_at)}</time></div><p>${escape(m.body||'[Média]')}</p>${m.media_type?badge('Pièce jointe'):''}<div class="adm-actions">${button('pin',m.pinned?'Désépingler':'Épingler',`data-id="${m.id}" data-value="${!m.pinned}"`)}${button('delete','Supprimer',`data-id="${m.id}"`,true)}</div></article>`).join(''):empty('Aucun message dans ce salon')}<div class="adm-actions">${button('room-prev','Précédent',number===1?'disabled':'')}${button('room-next','Suivant',number*r.pageSize>=r.total?'disabled':'')}</div>`);
      sub.querySelectorAll('[data-do]').forEach(b=>b.onclick=async()=>{try{if(b.dataset.do==='room-prev')return roomMessages(id,number-1);if(b.dataset.do==='room-next')return roomMessages(id,number+1);if(b.dataset.do==='pin'){b.disabled=true;await json(`/api/messages/${b.dataset.id}/pin`,'PATCH',{pinned:b.dataset.value==='true'});return roomMessages(id,number);}formDialog('Supprimer ce message',`<p>Le message et sa pièce jointe seront définitivement retirés du salon.</p>${reasonField()}`,body=>json(`/api/admin/messages/${b.dataset.id}`,'DELETE',body),'Supprimer le message');}catch(e){const el=sub.querySelector('.adm-sub-error');el.hidden=false;el.textContent=e.message;b.disabled=false;}});
    }catch(e){if(ticket===subRevision)sub.querySelector('.adm-sub-content').textContent=e.message;}
  }
  root.addEventListener('click',async e=>{
    const tabButton=e.target.closest('[data-tab]');if(tabButton){go(tabButton.dataset.tab);return;}
    const b=e.target.closest('[data-do]');if(!b)return;const action=b.dataset.do,id=b.dataset.id;
    try{
      if(action==='close'){reset();return;}if(action==='refresh'){await load();return;}if(action==='prev'||action==='next'){page+=action==='prev'?-1:1;await load();return;}
      if(action.startsWith('go-'))return go(action.slice(3));if(action==='member')return member(id);
      if(action.startsWith('report-')){
        const r=data.items.find(r=>String(r.id)===id);if(!r)return;
        const path=`/api/admin/reports/${id}`;
        if(action==='report-media'){
          openSub('Pièce jointe signalée','<p>Chargement de la pièce jointe…</p>');const ticket=subRevision;
          const response=await api(path+'/media');const blob=await response.blob();if(ticket!==subRevision||!sub.open)return;
          const url=URL.createObjectURL(blob);mediaUrls.add(url);const box=sub.querySelector('.adm-sub-content');box.replaceChildren();
          const el=document.createElement(blob.type.startsWith('image/')?'img':blob.type.startsWith('audio/')?'audio':'video');
          el.className='adm-evidence-media';el.src=url;if(el.tagName==='IMG')el.alt='Pièce jointe du message signalé';else{el.controls=true;el.preload='metadata';}box.append(el);return;
        }
        if(action==='report-edit')return formDialog(`Examiner le signalement #${id}`,`<label>Décision<select name="status">${options([['pending','À traiter / rouvrir'],['resolved','Traité'],['dismissed','Classer sans suite']],r.status)}</select></label><label>Note interne<textarea name="note" minlength="3" maxlength="2000" required rows="5">${escape(r.admin_note)}</textarea></label><p class="adm-muted">La note reste interne. Le membre ayant signalé sera informé d’un changement de statut.</p>`,body=>json(path,'PATCH',{...body,expectedStatus:r.status}),'Enregistrer la décision');
        if(action==='report-delete')return formDialog('Retirer le message signalé',`<p>Le message sera supprimé pour ses destinataires. L’extrait du signalement sera conservé dans le dossier.</p>${reasonField()}`,body=>json(path+'/message','DELETE',body),'Retirer le message');
        b.disabled=true;await json(path,'PATCH',action==='report-assign'?{assignment:r.assigned_to===owner?'none':'me'}:{priority:r.priority==='urgent'?'normal':'urgent'});success('Signalement actualisé.');return load();
      }
      if(action==='room-settings'){
        const r=data.find(r=>r.id===id);return formDialog(r.title,`<label>Écriture<select name="readOnly">${options([['false','Ouverte à tous les membres autorisés'],['true','Lecture seule (administrateurs uniquement)']],String(r.read_only))}</select></label><label>Délai entre deux messages<select name="slowSeconds">${options([['0','Aucun délai supplémentaire'],['5','5 secondes'],['10','10 secondes'],['30','30 secondes'],['60','60 secondes']],String(r.slow_seconds))}</select></label><label>Message d’information<textarea name="notice" maxlength="300" rows="2">${escape(r.notice)}</textarea></label>${reasonField()}`,body=>json(`/api/admin/rooms/${encodeURIComponent(id)}`,'PATCH',{...body,readOnly:body.readOnly==='true',slowSeconds:Number(body.slowSeconds)}),'Enregistrer le salon');
      }
      if(action==='room-messages')return roomMessages(id);
      if(action==='group-pause'){const g=data.items.find(x=>x.id===id);return formDialog(g.paused?'Réouvrir le groupe':'Mettre le groupe en pause',`<p>${escape(g.name)} · Le motif sera visible par les membres lorsqu’un envoi est bloqué.</p>${reasonField()}`,body=>json(`/api/admin/groups/${encodeURIComponent(id)}`,'PATCH',{...body,paused:!g.paused}));}
    }catch(e){if(sub.open){const el=sub.querySelector('.adm-sub-error');el.hidden=false;el.textContent=e.message;sub.querySelector('.adm-sub-content').removeAttribute('aria-busy');}else error(e);b.disabled=false;}
  });
  root.addEventListener('cancel',reset);root.addEventListener('close',()=>{revision++;if(sub.open)sub.close();content.innerHTML='';});
  document.querySelector('#adminBtn').onclick=()=>{const u=getUser();if(!u?.admin)return;owner=u.id;root.showModal();go('overview');};
  return {reset};
}
